347	    // label becomes the queued one — so the gate clears by being acted on and a
348	    // second tick finds nothing to adopt. Re-requesting is re-applying the label.
349	    for (const req of requests.filter((r) => r.state === 'open' && r.labels.has(REQUEST_LABEL))) {
350	      const it = createIssue({
