352	        labels: ['task:ready'], qualifier: `#${req.number}`,
353	        request: req.number, model: modelFor(req.labels),
354	      });
355	      req.labels.delete(REQUEST_LABEL);
356	      req.labels.add(QUEUED_LABEL);
357	      record('adopt', { task: REQUEST_TASK, issue: it.number, request: req.number, model: it.model });
