1	// A discrete-event simulator of the tasks-dispatch spec (DESIGN.md), so the
2	// scenario play-throughs in SCENARIOS.md are executable instead of prose-only.
3	//
4	// What it models faithfully: virtual time, the tick's three jobs (calendar-only
5	// instantiation with both guards and the first-item rule, readiness, the
6	// executing-leash reclaim), the executor loop (pick order, same-title mutex,
7	// the `after` yield, claim, validate, the single precondition evaluation, the
8	// roll, the work step/hand-off/converge as timed phases, heartbeat comments
9	// during the work step so the leash measures executor death rather than work
10	// duration), at-most-once invocation (one call per item, never retried — the
11	// fired/refused/unanswered trichotomy of DESIGN §6.6), the readiness re-check
12	// on close (F1, reopened 2026-08-15), the janitor's stale-ready escalation,
13	// and the force-is-waking lever. `afterMode: 'blocked-by'` exists solely so
14	// S24 can demonstrate the starvation that ruled that wiring out.
15	//
16	// What it deliberately does NOT model is inventoried in README.md's "The
17	// unsimulated world" — one row per boundary (cron delivery, list freshness,
18	// label non-atomicity, comment-id ordering, event delivery, secrets, …) with
19	// what defends the design there. A bug living exactly on one of those
20	// boundaries will not surface here; executor contention IS modeled, as
21	// stale-snapshot races over the claim protocol (raceExecutorsAt).
22	//
23	// Time is milliseconds UTC; events run strictly in time order (FIFO within a
24	// tie). Nothing here sleeps, threads, or reads the wall clock.
25	
26	const MIN = 60_000;
27	const HOUR = 60 * MIN;
28	const DAY = 24 * HOUR;
29	
30	export const T = (iso) => Date.parse(iso.length === 17 ? iso.replace('Z', ':00Z') : iso);
31	const iso = (t) => new Date(t).toISOString().slice(0, 16) + 'Z';
32	
33	// ---- frequency → anchors ----------------------------------------------------
34	// daily-Nh anchors at N:00Z, plain daily at 04:00Z, hourly at :00, weekly at
35	// Sunday 04:00Z. mostRecentAnchor is the latest anchor ≤ now; nextAnchor the
36	// earliest one > now.
37	
38	// daily-Nh / daily+Nh offset the schedule's daily hour (default 4), per the
39	// engine's DAILY_OFFSETS: daily-2h → 02:00Z, daily-1h → 03:00Z, daily → 04:00Z.
40	function anchorHour(frequency) {
41	  const m = /^daily([+-]\d+)h$/.exec(frequency);
42	  if (m) return 4 + Number(m[1]);
43	  if (frequency === 'daily') return 4;
44	  if (frequency === 'weekly') return 4;
45	  throw new Error(`no anchor hour for ${frequency}`);
46	}
47	
48	export function periodMs(frequency) {
49	  if (frequency === 'hourly') return HOUR;
50	  if (frequency === 'weekly') return 7 * DAY;
51	  return DAY; // daily, daily-Nh
52	}
53	
54	export function mostRecentAnchor(frequency, now) {
55	  if (frequency === 'manual') return null;
56	  if (frequency === 'hourly') return Math.floor(now / HOUR) * HOUR;
57	  const d = new Date(now);
58	  let a = Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate(), anchorHour(frequency));
59	  if (a > now) a -= DAY;
60	  if (frequency === 'weekly') {
61	    while (new Date(a).getUTCDay() !== 0 || a > now) a -= DAY;
62	  }
63	  return a;
64	}
65	
66	export function nextAnchor(frequency, now) {
67	  let a = mostRecentAnchor(frequency, now);
68	  do a += periodMs(frequency); while (a <= now);
69	  return a;
70	}
71	
72	// ---- the simulator ----------------------------------------------------------
73	
74	// ---- ad-hoc requests (DESIGN §16) ------------------------------------------
75	// The request vocabulary lives on an ORDINARY issue and is written by the tick
76	// and by whoever converges the item — never by a person past the first mark.
77	export const REQUEST_LABEL = 'claude-task';
78	export const QUEUED_LABEL = 'claude-queued';
79	// Not "done": the run's success leaves a PR a person must still merge, and the
80	// item parks at `task:needs-human-approval` rather than closing. The issue says
81	// what is true of it — a change is written and waiting on review.
82	export const IN_REVIEW_LABEL = 'claude-in-review';
83	export const MODEL_LABEL_PREFIX = 'claude-model:';
84	export const REQUEST_TASK = 'engine/implement-request';
85	export const MODEL_FAMILIES = ['opus', 'sonnet', 'haiku'];
86	export const DEFAULT_MODEL = 'opus';
87	// Push permission, read from the permission API (F30). The payload's
88	// `author_association` alone is broader than push — MEMBER is any org member and
89	// COLLABORATOR includes read-only collaborators — so it may prefilter, but the
90	// verdict is the permission read, which is what the sim models.
91	export const PUSH_PERMISSIONS = ['admin', 'maintain', 'write'];
92	export const APPROVAL_RE = /^\s*\/claude\s+go\b/im;
93	
94	// Eligibility over one request's payload — the built-in precondition's core,
95	// modeled here in the shape the engine will carry it: candidate logins (the
96	// author, then approving commenters) judged by their permission on the repo.
97	export function eligible(req, permissionOf) {
98	  if (PUSH_PERMISSIONS.includes(permissionOf(req.author))) return { ok: true, why: `opened by ${req.author}, who has push access` };
99	  const approval = (req.comments ?? []).find((c) => APPROVAL_RE.test(c.body ?? '') && PUSH_PERMISSIONS.includes(permissionOf(c.login)));
100	  if (approval) return { ok: true, why: `approved by ${approval.login} with /claude go` };
101	  return { ok: false, why: 'neither opened nor approved by anyone with push access' };
102	}
103	
104	// The model a request asks for. An unrecognized family falls back to the default
105	// rather than to nothing — a request nobody can run would look accepted forever.
106	export function modelFor(labels) {
107	  const asked = [...labels].filter((l) => l.startsWith(MODEL_LABEL_PREFIX)).map((l) => l.slice(MODEL_LABEL_PREFIX.length));
108	  return MODEL_FAMILIES.find((f) => asked.includes(f)) ?? DEFAULT_MODEL;
109	}
